#include <iostream>
#include <string_view>

int main() {
    // C++17 string_view demonstrates modern language evolution
    constexpr std::string_view creator = "Bjarne Stroustrup";
    constexpr int cpp_origin_year = 1983;

    std::cout << "Language: C++\n";
    std::cout << "Origin Year: " << cpp_origin_year << "\n";
    std::cout << "Creator: " << creator << "\n";
    return 0;
}

